gameActivityImportAdditions.insert:
import android.database.Cursor;
import android.content.ContentResolver;
import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.Matrix;
import android.net.Uri;
import android.provider.OpenableColumns;
import androidx.activity.result.PickVisualMediaRequest;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.exifinterface.media.ExifInterface;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import org.json.JSONObject;

gameActivityClassAdditions.insert:
private static final int OPEN_MOBILE_PHOTO_PICKER_REQUEST = 19792;
private long OpenMobilePhotoPickerRequestId = 0L;
private static final int OPEN_MOBILE_MAX_TEXTURE_DIMENSION = 4096;
private static final long OPEN_MOBILE_MAX_SOURCE_BYTES = 256L * 1024L * 1024L;

public native void nativeOpenMobilePhotoPicked(long requestId, String cachedImagePath, String metadataJson);
public native void nativeOpenMobilePhotoPickCancelled(long requestId);
public native void nativeOpenMobilePhotoPickFailed(long requestId, String errorMessage);

public boolean AndroidThunkJava_OpenMobilePhotoPicker(final long requestId)
{
    try
    {
        GameActivity.this.runOnUiThread(new Runnable()
        {
            @Override
            public void run()
            {
                if (OpenMobilePhotoPickerRequestId != 0L)
                {
                    nativeOpenMobilePhotoPickFailed(requestId, "The previous photo picker is still closing. Try again after it closes.");
                    return;
                }
                OpenMobilePhotoPickerRequestId = requestId;
                try
                {
                    ActivityResultContracts.PickVisualMedia contract =
                        new ActivityResultContracts.PickVisualMedia();
                    PickVisualMediaRequest request = new PickVisualMediaRequest.Builder()
                        .setMediaType(ActivityResultContracts.PickVisualMedia.ImageOnly.INSTANCE)
                        .build();
                    Intent intent = contract.createIntent(activityContext, request);
                    GameActivity.this.startActivityForResult(intent, OPEN_MOBILE_PHOTO_PICKER_REQUEST);
                }
                catch (Exception exception)
                {
                    OpenMobilePhotoPickerRequestId = 0L;
                    nativeOpenMobilePhotoPickFailed(requestId,
                        "Unable to open Android's photo picker: " + exception.getMessage()
                    );
                }
            }
        });
        return true;
    }
    catch (Exception exception)
    {
        Log.error("OpenMobile photo picker launch failed: " + exception.getMessage());
        return false;
    }
}

public void AndroidThunkJava_CancelOpenMobilePhotoPicker(final long requestId)
{
    GameActivity.this.runOnUiThread(() ->
    {
        if (OpenMobilePhotoPickerRequestId == requestId)
        {
            try
            {
                GameActivity.this.finishActivity(OPEN_MOBILE_PHOTO_PICKER_REQUEST);
            }
            catch (RuntimeException exception)
            {
                Log.error("OpenMobile photo picker dismissal failed: " + exception.getMessage());
            }
        }
    });
}

private String OpenMobileExifString(ExifInterface exif, String tag)
{
    String value = exif.getAttribute(tag);
    return value == null ? "" : value;
}

private Bitmap OpenMobileApplyExifOrientation(Bitmap source, int orientation)
{
    Matrix matrix = new Matrix();
    switch (orientation)
    {
        case ExifInterface.ORIENTATION_FLIP_HORIZONTAL:
            matrix.setScale(-1.0f, 1.0f);
            break;
        case ExifInterface.ORIENTATION_ROTATE_180:
            matrix.setRotate(180.0f);
            break;
        case ExifInterface.ORIENTATION_FLIP_VERTICAL:
            matrix.setRotate(180.0f);
            matrix.postScale(-1.0f, 1.0f);
            break;
        case ExifInterface.ORIENTATION_TRANSPOSE:
            matrix.setRotate(90.0f);
            matrix.postScale(-1.0f, 1.0f);
            break;
        case ExifInterface.ORIENTATION_ROTATE_90:
            matrix.setRotate(90.0f);
            break;
        case ExifInterface.ORIENTATION_TRANSVERSE:
            matrix.setRotate(-90.0f);
            matrix.postScale(-1.0f, 1.0f);
            break;
        case ExifInterface.ORIENTATION_ROTATE_270:
            matrix.setRotate(-90.0f);
            break;
        default:
            return source;
    }

    Bitmap transformed = Bitmap.createBitmap(
        source,
        0,
        0,
        source.getWidth(),
        source.getHeight(),
        matrix,
        true
    );
    if (transformed != source)
    {
        source.recycle();
    }
    return transformed;
}

private void OpenMobileProcessSelectedPhoto(final long requestId, final Uri uri)
{
    new Thread(new Runnable()
    {
        @Override
        public void run()
        {
            File outputFile = null;
            File sourceFile = null;
            try
            {
                ContentResolver resolver = activityContext.getContentResolver();
                String fileName = "Selected photo";
                long originalFileSize = 0L;

                Cursor cursor = null;
                try
                {
                    cursor = resolver.query(
                        uri,
                        new String[] { OpenableColumns.DISPLAY_NAME, OpenableColumns.SIZE },
                        null,
                        null,
                        null
                    );
                    if (cursor != null && cursor.moveToFirst())
                    {
                        int nameIndex = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME);
                        int sizeIndex = cursor.getColumnIndex(OpenableColumns.SIZE);
                        if (nameIndex >= 0 && !cursor.isNull(nameIndex))
                        {
                            fileName = cursor.getString(nameIndex);
                        }
                        if (sizeIndex >= 0 && !cursor.isNull(sizeIndex))
                        {
                            originalFileSize = cursor.getLong(sizeIndex);
                        }
                    }
                }
                finally
                {
                    if (cursor != null)
                    {
                        cursor.close();
                    }
                }

                String mimeType = resolver.getType(uri);
                if (mimeType == null)
                {
                    mimeType = "image/*";
                }

                if (originalFileSize > OPEN_MOBILE_MAX_SOURCE_BYTES)
                {
                    throw new Exception("The selected image is larger than the 256 MB import limit.");
                }

                File outputDirectory = new File(activityContext.getCacheDir(), "open_mobile_photo_picker");
                if (!outputDirectory.exists() && !outputDirectory.mkdirs())
                {
                    throw new Exception("The app's photo cache directory could not be created.");
                }

                sourceFile = new File(outputDirectory, "source_" + System.nanoTime() + ".bin");
                long copiedBytes = 0L;
                try (InputStream selectedStream = resolver.openInputStream(uri);
                     FileOutputStream sourceOutput = new FileOutputStream(sourceFile))
                {
                    if (selectedStream == null)
                    {
                        throw new Exception("The selected image could not be opened.");
                    }

                    byte[] copyBuffer = new byte[64 * 1024];
                    int bytesRead;
                    while ((bytesRead = selectedStream.read(copyBuffer)) != -1)
                    {
                        copiedBytes += bytesRead;
                        if (copiedBytes > OPEN_MOBILE_MAX_SOURCE_BYTES)
                        {
                            throw new Exception("The selected image is larger than the 256 MB import limit.");
                        }
                        sourceOutput.write(copyBuffer, 0, bytesRead);
                    }
                }
                if (originalFileSize <= 0L)
                {
                    originalFileSize = copiedBytes;
                }

                BitmapFactory.Options bounds = new BitmapFactory.Options();
                bounds.inJustDecodeBounds = true;
                try (InputStream boundsStream = new FileInputStream(sourceFile))
                {
                    BitmapFactory.decodeStream(boundsStream, null, bounds);
                }

                int originalWidth = Math.max(0, bounds.outWidth);
                int originalHeight = Math.max(0, bounds.outHeight);

                int orientation = ExifInterface.ORIENTATION_UNDEFINED;
                String dateTaken = "";
                String cameraMake = "";
                String cameraModel = "";
                String lensModel = "";
                double aperture = 0.0;
                double exposureTime = 0.0;
                int iso = 0;
                double focalLength = 0.0;
                boolean hasLocation = false;
                double latitude = 0.0;
                double longitude = 0.0;

                try (InputStream exifStream = new FileInputStream(sourceFile))
                {
                    if (exifStream != null)
                    {
                        ExifInterface exif = new ExifInterface(exifStream);
                        orientation = exif.getAttributeInt(
                            ExifInterface.TAG_ORIENTATION,
                            ExifInterface.ORIENTATION_UNDEFINED
                        );
                        dateTaken = OpenMobileExifString(exif, ExifInterface.TAG_DATETIME_ORIGINAL);
                        if (dateTaken.length() == 0)
                        {
                            dateTaken = OpenMobileExifString(exif, ExifInterface.TAG_DATETIME);
                        }
                        cameraMake = OpenMobileExifString(exif, ExifInterface.TAG_MAKE);
                        cameraModel = OpenMobileExifString(exif, ExifInterface.TAG_MODEL);
                        lensModel = OpenMobileExifString(exif, ExifInterface.TAG_LENS_MODEL);
                        aperture = exif.getAttributeDouble(ExifInterface.TAG_F_NUMBER, 0.0);
                        exposureTime = exif.getAttributeDouble(ExifInterface.TAG_EXPOSURE_TIME, 0.0);
                        iso = exif.getAttributeInt(ExifInterface.TAG_PHOTOGRAPHIC_SENSITIVITY, 0);
                        focalLength = exif.getAttributeDouble(ExifInterface.TAG_FOCAL_LENGTH, 0.0);

                        double[] location = exif.getLatLong();
                        hasLocation = location != null && location.length >= 2;
                        if (hasLocation)
                        {
                            latitude = location[0];
                            longitude = location[1];
                        }
                    }
                }
                catch (Exception metadataException)
                {
                    Log.warn("OpenMobile could not read EXIF metadata: " + metadataException.getMessage());
                }

                BitmapFactory.Options decodeOptions = new BitmapFactory.Options();
                decodeOptions.inPreferredConfig = Bitmap.Config.ARGB_8888;
                decodeOptions.inSampleSize = 1;
                int largestDimension = Math.max(originalWidth, originalHeight);
                while (largestDimension / decodeOptions.inSampleSize > OPEN_MOBILE_MAX_TEXTURE_DIMENSION)
                {
                    decodeOptions.inSampleSize *= 2;
                }

                Bitmap bitmap;
                try (InputStream bitmapStream = new FileInputStream(sourceFile))
                {
                    bitmap = BitmapFactory.decodeStream(bitmapStream, null, decodeOptions);
                }

                if (bitmap == null)
                {
                    throw new Exception("Android could not decode this image format.");
                }

                bitmap = OpenMobileApplyExifOrientation(bitmap, orientation);
                outputFile = new File(outputDirectory, "photo_" + System.nanoTime() + ".jpg");
                try (FileOutputStream output = new FileOutputStream(outputFile))
                {
                    if (!bitmap.compress(Bitmap.CompressFormat.JPEG, 92, output))
                    {
                        throw new Exception("Android could not encode the selected photo.");
                    }
                }
                finally
                {
                    bitmap.recycle();
                }

                JSONObject metadata = new JSONObject();
                metadata.put("fileName", fileName);
                metadata.put("mimeType", mimeType);
                metadata.put("fileSizeBytes", originalFileSize);
                metadata.put("width", originalWidth);
                metadata.put("height", originalHeight);
                metadata.put("dateTaken", dateTaken);
                metadata.put("exifOrientation", orientation);
                metadata.put("cameraMake", cameraMake);
                metadata.put("cameraModel", cameraModel);
                metadata.put("lensModel", lensModel);
                metadata.put("aperture", aperture);
                metadata.put("exposureTimeSeconds", exposureTime);
                metadata.put("iso", iso);
                metadata.put("focalLengthMm", focalLength);
                metadata.put("hasLocation", hasLocation);
                if (hasLocation)
                {
                    metadata.put("latitude", latitude);
                    metadata.put("longitude", longitude);
                }

                sourceFile.delete();
                sourceFile = null;
                nativeOpenMobilePhotoPicked(requestId, outputFile.getAbsolutePath(), metadata.toString());
            }
            catch (Exception exception)
            {
                if (sourceFile != null && sourceFile.exists())
                {
                    sourceFile.delete();
                }
                if (outputFile != null && outputFile.exists())
                {
                    outputFile.delete();
                }
                Log.error("OpenMobile photo import failed: " + exception.getMessage());
                nativeOpenMobilePhotoPickFailed(requestId,
                    "The selected Android photo could not be imported: " + exception.getMessage()
                );
            }
        }
    }, "OpenMobilePhotoImport").start();
}

gameActivityOnActivityResultAdditions.insert:
if (requestCode == OPEN_MOBILE_PHOTO_PICKER_REQUEST && OpenMobilePhotoPickerRequestId != 0L)
{
    final long photoRequestId = OpenMobilePhotoPickerRequestId;
    OpenMobilePhotoPickerRequestId = 0L;
    if (resultCode != RESULT_OK || data == null || data.getData() == null)
    {
        nativeOpenMobilePhotoPickCancelled(photoRequestId);
    }
    else
    {
        OpenMobileProcessSelectedPhoto(photoRequestId, data.getData());
    }
}

